use infinite_store::*;use std::{fs,path::PathBuf,thread,time::{Duration,Instant}};
fn dir(label:&str)->PathBuf{let root=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../.local/server-core/m6/test-data");fs::create_dir_all(&root).unwrap();let stamp=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos();root.join(format!("service-{label}-{}-{stamp}",std::process::id()))}
fn put(id:u64,value:&[u8])->Change{Change{key:RecordKey{table:1,id},value:Some(value.into())}}
fn poll(s:&mut JournalService)->Completion{let until=Instant::now()+Duration::from_secs(10);loop{if let Some(c)=s.try_poll().unwrap(){return c;}assert!(Instant::now()<until,"worker did not return receipt");thread::sleep(Duration::from_millis(1));}}
#[test]
fn unpolled_receipts_keep_capacity_reserved_and_rejection_returns_input(){
 let path=dir("bound");let opts=JournalOptions::default();let j=Journal::create(&path,[1;16],opts).unwrap();let mut s=JournalService::start(j,ServiceOptions{outstanding:1,retained_bytes:1024}).unwrap();let first=s.try_commit(None,vec![put(1,b"a")]).unwrap();let data=vec![put(2,b"b")];let denied=s.try_commit(None,data.clone()).unwrap_err();assert_eq!(denied.reason,SubmitError::Full);assert_eq!(denied.changes,data);assert_eq!(s.outstanding(),1);assert!(s.retained_bytes()>0);let c=poll(&mut s);assert_eq!(c.ticket,first.id());assert!(matches!(c.kind,CompletionKind::Commit(Ok(_))));assert_eq!(s.outstanding(),0);assert_eq!(s.retained_bytes(),0);assert!(!first.cancel());s.try_commit(None,denied.changes).unwrap();let done=s.shutdown();done.worker.unwrap();assert_eq!(done.completions.len(),1);assert_eq!(recover(path,opts).unwrap().mark.sequence,2);
}
#[test]
fn fifo_receipts_stale_base_and_checkpoint_converge(){
 let path=dir("fifo");let opts=JournalOptions::default();let j=Journal::create(&path,[2;16],opts).unwrap();let initial=j.mark();let mut s=JournalService::start(j,ServiceOptions::default()).unwrap();for i in 0..20{s.try_commit(None,vec![put(i,&[i as u8])]).unwrap();}let cp=s.try_checkpoint().unwrap();for i in 20..40{s.try_commit(None,vec![put(i,&[i as u8])]).unwrap();}let stale=s.try_commit(Some(initial),vec![put(100,b"stale")]).unwrap();let out=s.shutdown();out.worker.unwrap();let mut sequences=Vec::new();let mut checkpoint=false;let mut rejected=false;for c in out.completions{match c.kind{CompletionKind::Commit(Ok(r))=>sequences.push(r.mark.sequence),CompletionKind::Checkpoint(Ok(mark))=>{assert_eq!(c.ticket,cp.id());assert_eq!(mark.sequence,20);checkpoint=true;},CompletionKind::Commit(Err(JournalError::Codec(StoreError::ChainMismatch)))=>{assert_eq!(c.ticket,stale.id());rejected=true;},other=>panic!("unexpected {other:?}")}}assert_eq!(sequences,(1..=40).collect::<Vec<_>>());assert!(checkpoint&&rejected);let r=recover(path,opts).unwrap();assert_eq!(r.mark.sequence,40);assert_eq!(r.records.len(),40);assert_eq!(r.replayed,20);
}
#[test]
fn byte_budget_counts_vector_capacity_and_failed_commit_does_not_advance_mark(){
 let path=dir("bytes");let opts=JournalOptions::default();let j=Journal::create(&path,[3;16],opts).unwrap();let initial=j.mark();let mut s=JournalService::start(j,ServiceOptions{outstanding:8,retained_bytes:512}).unwrap();let mut oversized=Vec::with_capacity(100);oversized.push(put(1,b"x"));let denied=s.try_commit(None,oversized).unwrap_err();assert_eq!(denied.reason,SubmitError::Oversize);assert_eq!(denied.changes.capacity(),100);assert_eq!(s.outstanding(),0);s.try_commit(None,vec![put(1,b"a"),put(1,b"b")]).unwrap();assert!(matches!(poll(&mut s).kind,CompletionKind::Commit(Err(JournalError::Codec(StoreError::UnsortedKeys)))));assert_eq!(s.confirmed_mark(),initial);s.try_commit(None,vec![put(2,b"ok")]).unwrap();let done=s.shutdown();done.worker.unwrap();assert_eq!(done.completions.len(),1);assert_eq!(recover(path,opts).unwrap().mark.sequence,1);
}
